import React from 'react';
import useForm from '@arco-design/web-react/es/Form/useForm';
import { CListEditor, Form, Rate, Typography } from '@cloud-materials/common';

import type { InitValue, Item, Value } from '../interface';

const options = [
  {
    value: 'Beijing',
    label: 'Beijing',
  },
  {
    value: 'Shanghai',
    label: 'Shanghai',
  },
  {
    value: 'Guangzhou',
    label: 'Guangzhou',
    disabled: true,
  },
  {
    value: 'Shenzhen',
    label: 'Shenzhen',
  },
];
const ItemKey = [
  {
    label: 'key',
    component: 'input' as 'input',
  },
];

const SelectItem = [
  {
    label: 'select',
    component: 'select' as 'select',
    cAsyncSelectProps: {
      options: ['Beijing', 'Shanghai', 'Guangzhou'],
      defaultValue: ['Beijing'],
    },
  },
] as Item[];

const Items = SelectItem.concat(ItemKey);
const initValue1 = [
  {
    value: {
      key: 'key',
      select: 'Beijing',
      value: 'value',
      multiple: ['multiple'],
      switch: true,
      radio: 'Shanghai',
      rate: 4,
    },
  },
  {
    value: {
      key: 'key2',
      value: 'value2',
      multiple: ['multiple'],
      select: 'Beijing',
      switch: true,
      radio: 'Shanghai',
      rate: 4,
    },
  },
];

export default () => {
  const onChangeDisableAdd = (values: Value[]) => {
    if (values[1] && values[1].key === 'key2') {
      return {
        disableAdd: true,
        disableAddTip: '当第二行输入的key值为key2时，不允许再添加行',
      };
    } else {
      return {
        disableAdd: false,
        disableAddTip: '',
      };
    }
  };

  const onChangeDisableIndex = (values: Value[]) => {
    if (values[1] && values[1].key === 'key2') {
      return {
        disableItemsIndex: [0, 1],
        disableItemsIndexTip: '第1,2行不许再修改和删除',
      };
    }
  };

  const onChangeKeepOneItem = (values: Value[]) => {
    if (values.length < 2) {
      return {
        disableItemsIndex: [
          {
            index: 0,
          },
        ],
        disableDelete: true,
        disableDeleteTip: '第一行不许删除',
      };
    } else {
      return {
        disableDelete: false,
      };
    }
  };

  const onChangeOnlyKeyAllowValue = (values: Value[]) => {
    const getRes = (index: number, disabled = true) => ({
      index,
      disableChange: {
        value: {
          disabled,
          tip: disabled ? '请先选择key' : undefined,
        },
      },
    });
    const res: (number | (Omit<InitValue, 'value'> & { index: number }))[] = [];
    values.forEach((val, index) => {
      if (val.key) {
        res.push(getRes(index, false));
      } else {
        res.push(getRes(index));
      }
    });
    return {
      disableItemsIndex: res,
    };
  };

  const onChangeOtherPops = (values: Value[]) => {
    const getRes = (index: number, display = true) => ({
      index,
      disableChange: {
        path: {
          style: display ? { display: 'block' } : { display: 'none' },
        },
      },
    });
    const res: (number | (Omit<InitValue, 'value'> & { index: number }))[] = [];
    values.forEach((val, index) => {
      if (val.isFormat) {
        res.push(getRes(index));
      } else {
        res.push(getRes(index, false));
      }
    });
    return {
      disableItemsIndex: res,
    };
  };

  const [form] = useForm();

  return (
    <div>
      <Form
        form={form}
        initialValues={{
          ['field-3']: [
            {
              key: 'key',
              select: 'Beijing',
            },
            {
              key: 'key',
              select: 'Beijing',
            },
          ],
          users: [
            {
              username: 'aaa',
              address: 'bbb',
            },
          ],
        }}
      >
        <Typography.Title heading={5}>用法1：通用TagEditor，一行中不存在key，value也不可以输入</Typography.Title>
        <CListEditor
          fieldName="field-0"
          items={[
            {
              label: 'key',
              component: 'select',
              cAsyncSelectProps: {
                allowClear: true,
                options,
              },
              width: 400,
            },
            { label: 'value', component: 'input', width: 400 },
          ]}
          onEditingDisableVerify={onChangeOnlyKeyAllowValue}
        />
        <Typography.Title heading={5}>用法2：当第二行输入的key值为key2时，不允许再添加行</Typography.Title>
        <CListEditor
          fieldName="field-1"
          items={Items}
          initValue={initValue1}
          onEditingDisableVerify={onChangeDisableAdd}
        />
        <Typography.Title heading={5}>用法3：当第二行输入的key值为key2时，第1,2行不许再修改和删除</Typography.Title>
        <CListEditor
          fieldName="field-2"
          items={Items}
          initValue={initValue1}
          onEditingDisableVerify={onChangeDisableIndex}
        />
        <Typography.Title heading={5}>用法4：使用form.initialValue传值 且 至少保留一行</Typography.Title>
        <CListEditor
          fieldName="field-3"
          items={Items.concat([
            {
              label: 'rate',
              component: <Rate />,
            },
          ])}
          onEditingDisableVerify={onChangeKeepOneItem}
        />
        <Typography.Title heading={5}>
          用法5：通过onEditingDisableVerify透传其他属性，注意这些透传属性会同时作用在Form.Item和组件上
        </Typography.Title>
        <Typography.Title heading={6}>
          用法5.1：通过修改style.display实现 当只有switch为true，才可见最后一个输入框
        </Typography.Title>
        <Form.Item label="数据盘">
          <CListEditor
            fieldName="field-4"
            items={[
              {
                label: 'type',
                component: 'select',
                cAsyncSelectProps: {
                  allowClear: true,
                  options: [{ label: '通用型SSD云硬盘', value: 'SSD' }, 'HDD'],
                },
                width: 200,
              },
              {
                label: 'size',
                component: {
                  component: 'InputNumber',
                  componentProps: { placeholder: '请输入数字' },
                },
                width: 200,
              },
              {
                label: 'isFormat',
                component: {
                  component: 'Switch',
                },
                triggerPropName: 'checked' as 'checked',
                addDefaultValue: false,
                width: 40,
              },
              {
                label: 'path',
                component: 'input',
                width: 400,
                arcoInputProps: {
                  placeholder: '请输入格式化地址',
