import React from 'react';
import { CListEditor, Form, Typography } from '@cloud-materials/common';
import type { Item } from '../interface';
import type { CPopoverVerifyRule } from '../../CPopoverVerify/interface';

const regName = /^([A-Za-z0-9][-A-Za-z0-9_.]*)?[A-Za-z0-9]$/;
const regPrefix = /^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$/;
function checkPrefix(prefix: string): boolean {
  return !(prefix.length > 253 || !regPrefix.test(prefix));
}
function checkName(name: string): boolean {
  return !(name.length > 63 || !regName.test(name));
}

export const PaaSKeyRules: CPopoverVerifyRule[] = [
  {
    message: '支持可选前缀和名称，使用分隔符（"/"）连',
    validator: (v, cb) => {
      if (v) {
        const arr = v?.split('/');
        if (arr?.length !== 2) cb('不符合输入规则');
      }
    },
  },
  {
    message: '前缀是由分隔符（"."）连接的一组 DNS 标签，长度 253 个字符以内',
    validator: (v, cb) => {
      if (v) {
        const arr = v?.split('/');
        const prefix = arr[0];
        if (!checkPrefix(prefix)) cb('不符合输入规则');
      }
    },
  },
  {
    message: `名称支持字母、数字及分隔符("-"、"_"、".")，需以字母、数字开头和结尾，长度 1 - 63 个字符`,
    validator: (v, cb) => {
      if (v) {
        const arr = v?.split('/');
        const name = arr[1];
        if (!checkName(name)) cb('不符合输入规则');
      }
    },
  },
];

const PaaSValueRules: CPopoverVerifyRule[] = [
  {
    message: '支持为空或以字母、数字及分隔符("-"、"_"、".")组成',
    validator: (v, cb) => {
      if (['-', '.', '_'].includes(v)) cb('不符合输入规则');
    },
  },
  {
    message: '需以字母、数字开头和结尾',
    validator: (v, cb) => {
      if (!/^(?![-._])[\w-.]{0,63}$/.test(v)) cb('不符合输入规则');
    },
  },
  { message: '长度 63 个字符以内', maxLength: 63 },
];

const InitValuesPaaS = [
  {
    value: {},
  },
];

const Items: Item[] = [
  {
    label: 'key',
    component: 'input',
    width: 400,
    rules: PaaSKeyRules,
  },
  {
    label: 'value',
    width: 200,
    component: 'input',
    rules: PaaSValueRules,
  },
];

export default () => {
  return (
    <div>
      <Form>
        <Typography.Title heading={5}>PaaS的规则，PaaS迁移示例</Typography.Title>
        <Form.Item label={'PaaS'}>
          <CListEditor
            fieldName="field-1"
            items={Items}
            initValue={InitValuesPaaS}
            repeatValidatorLabel="key"
            repeatMessage="键名不能重复"
            requireLabel="key"
            maxLen={20}
          />
        </Form.Item>
      </Form>
    </div>
  );
};

