import type { CPopoverVerifyRule } from '../../CPopoverVerify/interface';

const { useForm } = Form;

const KEY_NOT_SYSTEM_MESSAGE = '不能以任何大小写形式的“volc:”开头';
const KV_VALIDATOR_MESSAGE = '只能包含语言字符、数字、空格和英文符号_.:/=+-@';

const IaaSKeyRules: CPopoverVerifyRule[] = [
  {
    message: '长度需要在1-128个字符内',
    minLength: 1,
    maxLength: 128,
  },
  {
    message: '不能以任何大小写形式的“volc:”开头',
    validator: (v, cb) => {
      if (/^[Vv][Oo][Ll][Cc]:/.test(v)) cb(KEY_NOT_SYSTEM_MESSAGE);
    },
  },
  {
    message: KV_VALIDATOR_MESSAGE,
    validator: (v, cb) => {
      // eslint-disable-next-line no-useless-escape
      if (!/^[\p{L}\p{Z}\p{N}_.:\/=+\-@]*$/gu.test(v)) cb(KV_VALIDATOR_MESSAGE);
    },
  },
];

const IaaSValueRules: CPopoverVerifyRule[] = [
  {
    message: '长度需要在0-256个字符内',
    maxLength: 256,
  },
  {
    message: KV_VALIDATOR_MESSAGE,
    validator: (v, cb) => {
      // eslint-disable-next-line no-useless-escape
      if (!/^[\p{L}\p{Z}\p{N}_.:\/=+\-@]*$/gu.test(v)) cb(KV_VALIDATOR_MESSAGE);
    },
  },
];

const InitValues = [
  {
    value: { key: 'volc:ecs', value: 'value' },
    rowDisabled: true,
    rowDisabledTip: '系统标签不可修改',
  },
  { value: { key: 'ecs', value: 'ecs' } },
  {
    value: { key: 'image', value: 'windows : 2012' },
  },
  {
    value: { key: 'flavor', value: 'ecs.g1.xlarge' },
  },
];

const Items: Item[] = [
  {
    label: 'key',
    component: 'input',
    width: 400,
    rules: IaaSKeyRules,
  },
  {
    label: 'value',
    width: 400,
    component: 'input',
    rules: IaaSValueRules,
  },
];

export default () => {
  const [form] = useForm();
  return (
    <div>
      <Form form={form}>
        <Typography.Title heading={5}>IaaS的规则，IaaS迁移示例</Typography.Title>
        <Form.Item label={'IaaS'}>
          <CListEditor
            fieldName="field-1"
            items={Items}
            initValue={InitValues}
            repeatValidatorLabel="key"
            repeatMessage="已经添加过该标签键"
            maxLen={20}
          />
        </Form.Item>
        <Button
          htmlType="submit"
          onClick={() => {
            form
              .validate()
              .then(res => {
                console.log(res);
              })
              .catch(err => {
                console.log(err);
              });
          }}
        >
          确定
        </Button>
      </Form>
    </div>
  );
};

import React from 'react';
