            {
              label: 'key',
              component: 'input' as 'input',
              width: 400,
              multiple: true,
              rules: multipleRules,
            },
          ]}
          initValue={initValue}
        />
        <Button htmlType="submit">确定</Button>
      </Form>
    </div>
  );
};

